$dll = "G:\truong\TCN HaTinh - 2019\Web\bin\SystemService.dll"
Write-Host "=== File info ==="
Get-Item $dll | Format-List FullName, Length, LastWriteTime
Write-Host "=== Assembly inspect ==="
$bytes = [System.IO.File]::ReadAllBytes($dll)
$asm = [System.Reflection.Assembly]::Load($bytes)
Write-Host ("FullName: " + $asm.FullName)
Write-Host ("ImageRuntimeVersion: " + $asm.ImageRuntimeVersion)
Write-Host "=== Referenced assemblies ==="
$asm.GetReferencedAssemblies() | ForEach-Object { $_.FullName }
Write-Host "=== Exported types ==="
try {
  $asm.GetExportedTypes() | ForEach-Object { $_.FullName }
} catch {
  Write-Host ("GetExportedTypes error: " + $_.Exception.Message)
  Write-Host "=== Defined types via Module ==="
  $asm.GetTypes() | ForEach-Object { $_.FullName }
}

Write-Host "=== Web\bin ==="
Get-ChildItem .\bin -File | Sort-Object Name | Format-Table Name, Length -AutoSize
Write-Host "=== InformationWeb\bin missing vs needed ==="
$needed = @('Control.dll','Global.dll','DCore.dll','Libs.dll','SystemObject.dll','DevExpress.XtraTreeList.v11.1.dll','DevExpress.XtraEditors.v11.1.dll','DevExpress.XtraGrid.v11.1.dll','DevExpress.Data.v11.1.dll','DevExpress.Utils.v11.1.dll','Microsoft.Office.Interop.Excel.dll')
foreach ($n in $needed) {
  $inWebBin = Test-Path (Join-Path '.\bin' $n)
  $inProjBin = Test-Path (Join-Path '.\InformationWeb\bin' $n)
  $inDoc = Test-Path (Join-Path '.\Document' $n)
  Write-Host ("{0,-40} Web\bin={1,-5} InfoWeb\bin={2,-5} Document={3}" -f $n, $inWebBin, $inProjBin, $inDoc)
}

Write-Host "`n=== SYS_SettingService public members ==="
$dll = (Get-Item -LiteralPath '.\bin\SystemService.dll').FullName
$bytes = [System.IO.File]::ReadAllBytes($dll)
$asm = [System.Reflection.Assembly]::Load($bytes)
$t = $asm.GetType('SystemService.SYS_SettingService')
$t.GetMembers() | ForEach-Object {
  if ($_.MemberType -eq 'Method' -or $_.MemberType -eq 'Property' -or $_.MemberType -eq 'Field') {
    $_.ToString()
  }
}

Write-Host "=== Control.dll locations near project ==="
Get-ChildItem -LiteralPath (Get-Location) -Filter "Control.dll" -Recurse -ErrorAction SilentlyContinue | Select-Object FullName, Length, LastWriteTime
Write-Host "`n=== Parent folders ==="
Get-ChildItem -LiteralPath (Split-Path (Get-Location)) -ErrorAction SilentlyContinue | Select-Object Name
Write-Host "`n=== Search SystemService.csproj limited ==="
$roots = @(
  (Join-Path (Split-Path (Get-Location)) '..'),
  'D:\1.PM\ZTXT',
  'D:\1.PM\CORE-Digalaxy',
  'G:\Web Libs'
)
foreach ($r in $roots) {
  if (Test-Path $r) {
    Write-Host ("Search in " + $r)
    Get-ChildItem -Path $r -Filter "SystemService.csproj" -Recurse -ErrorAction SilentlyContinue | Select-Object -First 5 FullName
    Get-ChildItem -Path $r -Filter "DevExpress.XtraEditors.v11.1.dll" -Recurse -ErrorAction SilentlyContinue | Select-Object -First 3 FullName
  } else {
    Write-Host ("Missing: " + $r)
  }
}
